package hexadecimal

import (
	"errors"
	"fmt"
)

// ParseHex converts a hexadecimal string to its decimal equivalent.
// It returns an error containing "syntax" for invalid input and
// "range" when the value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errors.New("syntax error: empty input")
	}

	var result int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid hexadecimal digit %q", r)
		}

		if result < 0 || result > (math.MaxInt64-digit)/16 {
			return 0, errors.New("range error: value out of range for int64")
		}
		result = result*16 + digit
	}

	return result, nil
}
